/**
 * Host half of the *native-route* variant.
 *
 * Difference to the gateway variant in the repository root:
 *
 *   gateway variant:  DSH → 127.0.0.1:8787 (own proxy) → Arena
 *   native variant:   DSH → api.arena.ai/v1            (llm-pi-ai, directly)
 *
 * There is no proxy process, no port, no catalog cache and no second HTTP
 * client. The route itself is declared in the profile composition by
 * `cordis.patch.yml` (generated by `bin/arena-setup.mjs --sync`), which uses
 * DeepSeek Harness' own `@deepseek-ai/dsh-llm-pi-ai` adapter with
 * `apiKeyEnv: ARENA_API_KEY`.
 *
 * This plugin half then has exactly one job: make sure that environment variable
 * exists inside the harness process, because a profile plugin cannot rely on the
 * shell environment the app was started from. It reads the key file written by
 * the setup CLI and injects it into `process.env` for this process only — never
 * into settings, the patch, a session or a log. Plus a one-shot connectivity
 * check so `harness.log` says why the route would fail.
 */
import { loadKey, KEY_ENV, maskKey } from './lib/credentials.js'
import { fetchCatalog } from './lib/catalog.js'

export const name = 'dsh-freemodels-arena-native'

function disabled() {
  return /^(1|true|yes|on)$/i.test(String(process.env.FREEMODELS_DISABLE ?? ''))
}

export function apply(ctx) {
  const log = {
    info: (message, fields) => ctx.logger?.info?.(`${name}: ${message}`, fields) ?? console.log(name, message, fields ?? ''),
    warn: (message, fields) => ctx.logger?.warn?.(`${name}: ${message}`, fields) ?? console.warn(name, message, fields ?? ''),
    error: (message, fields) => ctx.logger?.error?.(`${name}: ${message}`, fields) ?? console.error(name, message, fields ?? ''),
  }

  if (disabled()) {
    log.info('disabled through FREEMODELS_DISABLE')
    return
  }

  const keyInfo = loadKey()
  if (keyInfo.key) {
    // Process-scoped only: the harness' llm-pi-ai route resolves
    // `apiKeyEnv: ARENA_API_KEY` through this environment.
    if (process.env[KEY_ENV] !== keyInfo.key) process.env[KEY_ENV] = keyInfo.key
    log.info('Arena key loaded for the native route', {
      source: keyInfo.source,
      key: maskKey(keyInfo.key),
      route: 'arena',
    })
  } else {
    log.warn('no Arena key available; the "arena" route will fail with MISSING_CREDENTIAL', {
      expected: `ARENA_API_KEY in the environment or ${keyInfo.keyFile}`,
      ...(keyInfo.error ? { problem: keyInfo.error } : {}),
      remedy: 'run: node bin/arena-setup.mjs',
    })
    return
  }

  // Non-blocking reachability probe: never delays boot, never throws.
  const controller = new AbortController()
  ctx.effect(() => () => controller.abort())
  void fetchCatalog({
    apiBase: process.env.ARENA_API_BASE,
    apiKey: keyInfo.key,
    signal: controller.signal,
  })
    .then(({ models }) => {
      log.info('Arena reachable for the native route', { models: models.length })
    })
    .catch(error => {
      const message = String(error?.message ?? error)
      const hint = /HTTP 401|HTTP 403/.test(message)
        ? 'Arena rejected the key or this client; free-router keys are limited to specific harnesses (see README).'
        : /timeout|abort/i.test(message)
          ? 'No answer from api.arena.ai within 15s; check proxy/firewall settings.'
          : undefined
      log.warn('Arena not reachable for the native route', { reason: message, ...(hint ? { hint } : {}) })
    })
}
